{% set bir_company = frappe.get_doc('Company', doc.company) %}
<div class="bir-sj-print">
    <style>
        .bir-sj-print {
            font-family: "Segoe UI", Arial, sans-serif;
            color: #000;
            background-color: #fff;
            padding: 5px;
        }
        .bir-header-sap {
            margin-bottom: 12px;
            border-bottom: 2px solid #000;
            padding-bottom: 8px;
        }
        .bir-header-sap h2 {
            text-align: center;
            font-weight: bold;
            text-transform: uppercase;
            margin-top: 0;
            margin-bottom: 10px;
            font-size: 16px;
            letter-spacing: 0.5px;
        }
        .sap-metadata-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 9.5px;
            line-height: 1.3;
        }
        .sap-metadata-table td {
            padding: 2px 4px !important;
            border: none !important;
        }
        .sap-metadata-table td.label-cell {
            font-weight: bold;
            width: 12%;
            text-align: left;
        }
        .sap-metadata-table td.value-cell {
            width: 38%;
            text-align: left;
        }
        .bir-period {
            font-size: 11px;
            font-weight: bold;
            margin-top: 5px;
            margin-bottom: 8px;
            text-transform: uppercase;
        }
        .bir-table {
            width: 100%;
            border-collapse: collapse;
            font-size: 9.5px;
        }
        .bir-table th, .bir-table td {
            border: 1px solid #000;
            padding: 4px 6px;
            text-align: left;
            white-space: nowrap; /* Prevent wrap */
        }
        .bir-table th {
            background-color: #fff;
            font-weight: bold;
            text-align: center;
            text-transform: uppercase;
        }
        .bir-table td.num-cell {
            text-align: right;
        }
        .bir-table tr.total-row td {
            font-weight: bold;
        }
        .bir-summary-section {
            margin-top: 20px;
            page-break-inside: avoid;
        }
        .bir-summary-section h3 {
            font-size: 11px;
            font-weight: bold;
            text-transform: uppercase;
            margin-bottom: 8px;
            border-bottom: 1px solid #000;
            padding-bottom: 2px;
            width: fit-content;
        }
        @media print {
            @page {
                size: landscape;
                margin: 6mm 4mm 4mm 4mm;
            }
            .bir-sj-print {
                width: 100%;
            }
            .bir-table {
                font-size: 7.5px;
            }
            .sap-metadata-table {
                font-size: 8.5px;
            }
        }
    </style>

    <div class="bir-header-sap">
        <h2>Sales Journal</h2>
        <table class="sap-metadata-table">
            <tr>
                <td class="label-cell">Company:</td>
                <td class="value-cell">{{ bir_company.company_name or doc.company }}</td>
                <td class="label-cell">Line of Business:</td>
                <td class="value-cell">{{ doc.line_of_business or '' }}</td>
            </tr>
            <tr>
                <td class="label-cell">Address:</td>
                <td class="value-cell">{{ doc.address_display or '' }}</td>
                <td class="label-cell">Zip:</td>
                <td class="value-cell">{{ doc.zip or '' }}</td>
            </tr>
            <tr>
                <td class="label-cell">TIN:</td>
                <td class="value-cell">{{ bir_company.tax_id or '' }}</td>
                <td class="label-cell">Email:</td>
                <td class="value-cell">{{ doc.email or '' }}</td>
            </tr>
            <tr>
                <td class="label-cell">RDO:</td>
                <td class="value-cell">{{ doc.rdo or '' }}</td>
                <td class="label-cell">Mobile / Tel:</td>
                <td class="value-cell">
                    {{ doc.mobile or '' }}{% if doc.telephone %} / {{ doc.telephone }}{% endif %}
                </td>
            </tr>
        </table>
    </div>

    <div class="bir-period">
        Period: {{ frappe.format(doc.from_date, {fieldtype: 'Date'}) if doc.from_date else '' }} to {{ frappe.format(doc.to_date, {fieldtype: 'Date'}) if doc.to_date else '' }}
    </div>

    <div style="overflow-x: auto; -webkit-overflow-scrolling: touch; width: 100%; margin-bottom: 20px;">
        <table class="bir-table">
            <thead>
                <tr>
                    <th>Entry Date</th>
                    <th>Payor</th>
                    <th>TIN</th>
                    <th>Address</th>
                    <th>Invoice No.</th>
                    <th>Goods/Services</th>
                    <th>Discount Type</th>
                    <th>Discount Amount</th>
                    <th>VATable Sales</th>
                    <th>Output VAT</th>
                    <th>Zero-Rated</th>
                    <th>VAT-Exempt</th>
                    <th>Total Sales</th>
                    <th>W/Tax</th>
                    <th>Total Receivable</th>
                    <th>Status / Ref. / Date</th>
                    <th>Payment Date</th>
                    <th>Remarks</th>
                </tr>
            </thead>
            <tbody>
                {% set totals = {
                    'discount': 0.0,
                    'vatable': 0.0,
                    'output_vat': 0.0,
                    'zero_rated': 0.0,
                    'exempt': 0.0,
                    'total_sales': 0.0,
                    'w_tax': 0.0,
                    'total_receivable': 0.0
                } %}
                {% for row in doc.sales_entries %}
                    <tr>
                        <td style="white-space: nowrap;">{{ frappe.format(row.date, {fieldtype: 'Date'}) if row.date else '' }}</td>
                        <td>{{ row.payor or '' }}</td>
                        <td>{{ row.tin or '' }}</td>
                        <td>{{ row.address or '' }}</td>
                        <td>{{ row.invoice_no or '' }}</td>
                        <td style="text-align: center;">{{ row.goods_services or '' }}</td>
                        <td>{{ row.discount_type or 'NONE' }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.discount_amount or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.vatable_sales or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.output_vat or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.zero_rated or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.vat_exempt or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.total_sales or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.w_tax or 0) }}</td>
                        <td class="num-cell">{{ "{:,.2f}".format(row.total_receivable or 0) }}</td>
                        <td style="font-weight: bold; text-align: center; color: #000;">{{ row.status_ref_date or '' }}</td>
                        <td style="text-align: center;">{{ row.payment_date or '-' }}</td>
                        <td>{{ row.remarks or '' }}</td>
                    </tr>
                    {% if totals.update({
                        'discount': totals.discount + (row.discount_amount or 0),
                        'vatable': totals.vatable + (row.vatable_sales or 0),
                        'output_vat': totals.output_vat + (row.output_vat or 0),
                        'zero_rated': totals.zero_rated + (row.zero_rated or 0),
                        'exempt': totals.exempt + (row.vat_exempt or 0),
                        'total_sales': totals.total_sales + (row.total_sales or 0),
                        'w_tax': totals.w_tax + (row.w_tax or 0),
                        'total_receivable': totals.total_receivable + (row.total_receivable or 0)
                    }) %}{% endif %}
                {% endfor %}
                <tr class="total-row">
                    <td colspan="7">TOTAL</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.discount) }}</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.vatable) }}</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.output_vat) }}</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.zero_rated) }}</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.exempt) }}</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.total_sales) }}</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.w_tax) }}</td>
                    <td class="num-cell">{{ "{:,.2f}".format(totals.total_receivable) }}</td>
                    <td></td>
                    <td></td>
                    <td></td>
                </tr>
            </tbody>
        </table>
    </div>

    <div class="bir-summary-section">
        <h3>Summary</h3>
        <table class="bir-table" style="width: 35%;">
            <thead>
                <tr>
                    <th>Summary</th>
                    <th>Value</th>
                </tr>
            </thead>
            <tbody>
                {% for row in doc.summary_entries %}
                    <tr>
                        <td>{{ row.summary }}</td>
                        <td class="num-cell">
                            {% if row.summary == 'Documents' %}
                                {{ "{:,.2f}".format(row.value or 0) }}
                            {% else %}
                                {{ "{:,.2f}".format(row.value or 0) }}
                            {% endif %}
                        </td>
                    </tr>
                {% endfor %}
            </tbody>
        </table>
    </div>
</div><style>
        .bir-table { width:100%; table-layout:fixed; }
        .bir-table th, .bir-table td { white-space:normal !important; overflow-wrap:anywhere; word-wrap:break-word; padding:3px 2px; }
        .bir-table thead { display:table-header-group; }
        .bir-table tr { page-break-inside:avoid; }
        @media print { .bir-table { font-size:7.5px; } }
        </style>

