    {# Group and render transactions by Account #}
    {% set grouped_accounts = [] %}
    {% for row in doc.gl_entries %}
        {% if row.account not in grouped_accounts %}
            {% if grouped_accounts.append(row.account) %}{% endif %}
        {% endif %}
    {% endfor %}

    {% for account in grouped_accounts | sort %}
        <div class="account-group">
            {% set parts = account.split(' - ') %}
            <div class="account-title">
                {{ parts[0] or '' }}{% if parts[1] %} - {{ parts[1] }}{% endif %}
            </div>

            <table class="bir-table">
                <thead>
                    <tr>
                        <th style="width: 15%;">Date</th>
                        <th style="width: 55%;">Description</th>
