                                <tr>
                                    <td style="white-space: nowrap;">{{ frappe.format(row.date, {fieldtype: 'Date'}) if row.date else '' }}</td>
                                    <td>{{ row.description or '' }}</td>
                                    <td class="num-cell">{{ "{:,.2f}".format(row.debit or 0) }}</td>
                                    <td class="num-cell">{{ "{:,.2f}".format(row.credit or 0) }}</td>
                                    <td class="num-cell">{{ "{:,.2f}".format(row.balance or 0) }}</td>
                                </tr>
                            {% endif %}
                        {% endif %}
                    {% endfor %}
                </tbody>
            </table>
        </div>
    {% endfor %}
